diff --git a/durability.go b/durability.go
new file mode 100644
index 00000000..63310ae1
--- /dev/null
+++ b/durability.go
@@ -0,0 +1,475 @@
+// Copyright 2026 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+)
+
+var (
+	// ErrJobExpired is returned by WaitForJobDurability when waiting for a job
+	// that has expired from the bounded retention window.
+	ErrJobExpired = errors.New("pebble: job durability expired")
+
+	// ErrJobUnknown is returned by WaitForJobDurability when waiting for a job
+	// that was never seen or has an ID of zero or less.
+	ErrJobUnknown = errors.New("pebble: unknown job durability id")
+
+	// ErrTooManyDurabilitySubscriptions is delivered by DurabilityNotify when
+	// outstanding subscriptions exceed the configured bound.
+	ErrTooManyDurabilitySubscriptions = errors.New("pebble: too many durability subscriptions")
+)
+
+// DurabilityStats provides a snapshot of the durability subsystem state.
+type DurabilityStats struct {
+	HighestDurableSeqNum   base.SeqNum
+	FirstErr               error
+	PendingWaiters         int64
+	TotalDurableCommits    uint64
+	TotalFailedCommits     uint64
+	CumulativeSyncDuration time.Duration
+	MaxSyncDuration        time.Duration
+}
+
+type jobState struct {
+	done chan struct{}
+	err  error
+}
+
+type durabilityManager struct {
+	mu sync.Mutex
+
+	batchDurableConfigured bool
+	durableCommitCount     uint64
+	durableCommitDuration  time.Duration
+
+	highestDurableSeqNum   base.SeqNum
+	firstErr               error
+	pendingWaiters         int64
+	totalDurableCommits    uint64
+	totalFailedCommits     uint64
+	cumulativeSyncDuration time.Duration
+	maxSyncDuration        time.Duration
+
+	broadcastCh chan struct{}
+
+	maxSubscriptions int
+	subscriptions    map[chan error]base.SeqNum
+
+	jobRetentionWindow  int
+	minSeenJobID        int
+	maxSeenJobID        int
+	lowestRetainedJobID int
+	inFlightJobs        map[int]*jobState
+	completedJobs       map[int]error
+	completedOrder      []int
+	expiredJobs         map[int]struct{}
+	expiredOrder        []int
+
+	closed   bool
+	closeErr error
+}
+
+func newDurabilityManager(batchDurableConfigured bool) *durabilityManager {
+	return &durabilityManager{
+		batchDurableConfigured: batchDurableConfigured,
+		broadcastCh:            make(chan struct{}),
+		maxSubscriptions:       4096,
+		subscriptions:          make(map[chan error]base.SeqNum),
+		jobRetentionWindow:     1024,
+		inFlightJobs:           make(map[int]*jobState),
+		completedJobs:          make(map[int]error),
+		expiredJobs:            make(map[int]struct{}),
+	}
+}
+
+func (s *durabilityManager) registerJob(jobID int) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	if s.minSeenJobID == 0 || jobID < s.minSeenJobID {
+		s.minSeenJobID = jobID
+	}
+	if jobID > s.maxSeenJobID {
+		s.maxSeenJobID = jobID
+	}
+
+	js := &jobState{
+		done: make(chan struct{}),
+	}
+	if s.closed {
+		js.err = s.closeErr
+		close(js.done)
+	}
+	s.inFlightJobs[jobID] = js
+}
+
+func (s *durabilityManager) onBatchDurable(info BatchDurableInfo, callback func(BatchDurableInfo)) {
+	s.mu.Lock()
+
+	s.cumulativeSyncDuration += info.SyncDuration
+	if info.SyncDuration > s.maxSyncDuration {
+		s.maxSyncDuration = info.SyncDuration
+	}
+
+	if info.Err != nil {
+		s.totalFailedCommits++
+		if s.firstErr == nil {
+			s.firstErr = info.Err
+		}
+	} else {
+		s.totalDurableCommits++
+		endSeq := info.SeqNum
+		if info.KeyCount > 0 {
+			endSeq = info.SeqNum + base.SeqNum(info.KeyCount) - 1
+		}
+		if endSeq > s.highestDurableSeqNum {
+			s.highestDurableSeqNum = endSeq
+		}
+		if s.batchDurableConfigured {
+			s.durableCommitCount++
+			s.durableCommitDuration += info.SyncDuration
+		}
+	}
+
+	// Update job tracking
+	if js, ok := s.inFlightJobs[info.JobID]; ok {
+		js.err = info.Err
+		close(js.done)
+		delete(s.inFlightJobs, info.JobID)
+	}
+	s.completedJobs[info.JobID] = info.Err
+	s.completedOrder = append(s.completedOrder, info.JobID)
+	if s.lowestRetainedJobID == 0 {
+		s.lowestRetainedJobID = info.JobID
+	}
+
+	for len(s.completedOrder) > s.jobRetentionWindow {
+		evicted := s.completedOrder[0]
+		s.completedOrder = s.completedOrder[1:]
+		delete(s.completedJobs, evicted)
+		s.expiredJobs[evicted] = struct{}{}
+		s.expiredOrder = append(s.expiredOrder, evicted)
+		if len(s.completedOrder) > 0 {
+			s.lowestRetainedJobID = s.completedOrder[0]
+		}
+		for len(s.expiredOrder) > 50000 {
+			oldest := s.expiredOrder[0]
+			s.expiredOrder = s.expiredOrder[1:]
+			delete(s.expiredJobs, oldest)
+		}
+	}
+
+	// Deliver to subscriptions
+	for ch, subSeq := range s.subscriptions {
+		if info.Err != nil {
+			ch <- info.Err
+			delete(s.subscriptions, ch)
+		} else if s.isDurableLocked(subSeq) {
+			ch <- nil
+			delete(s.subscriptions, ch)
+		}
+	}
+
+	// Wake up any waiters
+	close(s.broadcastCh)
+	s.broadcastCh = make(chan struct{})
+
+	s.mu.Unlock()
+
+	if callback != nil {
+		callback(info)
+	}
+}
+
+func (s *durabilityManager) onClose(closeErr error) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	if s.closed {
+		return
+	}
+	s.closed = true
+	s.closeErr = closeErr
+
+	for id, js := range s.inFlightJobs {
+		js.err = closeErr
+		close(js.done)
+		delete(s.inFlightJobs, id)
+	}
+
+	for ch := range s.subscriptions {
+		ch <- closeErr
+		delete(s.subscriptions, ch)
+	}
+
+	close(s.broadcastCh)
+	s.broadcastCh = make(chan struct{})
+}
+
+func (s *durabilityManager) isDurableLocked(seqNum base.SeqNum) bool {
+	if seqNum == 0 {
+		return s.totalDurableCommits > 0
+	}
+	return s.totalDurableCommits > 0 && s.highestDurableSeqNum >= seqNum
+}
+
+func (s *durabilityManager) isExpiredLocked(jobID int) bool {
+	if _, ok := s.expiredJobs[jobID]; ok {
+		return true
+	}
+	if s.minSeenJobID > 0 && jobID >= s.minSeenJobID && s.lowestRetainedJobID > 0 && jobID < s.lowestRetainedJobID {
+		return true
+	}
+	return false
+}
+
+func (s *durabilityManager) waitForDurability(ctx context.Context, seqNum base.SeqNum) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	for {
+		if s.closeErr != nil {
+			return s.closeErr
+		}
+		if s.firstErr != nil {
+			return s.firstErr
+		}
+		if s.isDurableLocked(seqNum) {
+			return nil
+		}
+
+		s.pendingWaiters++
+		ch := s.broadcastCh
+		s.mu.Unlock()
+
+		select {
+		case <-ctx.Done():
+			s.mu.Lock()
+			s.pendingWaiters--
+			// Precedence: durability/close errors take precedence over context cancellation
+			if s.closeErr != nil {
+				return s.closeErr
+			}
+			if s.firstErr != nil {
+				return s.firstErr
+			}
+			if s.isDurableLocked(seqNum) {
+				return nil
+			}
+			return ctx.Err()
+		case <-ch:
+			s.mu.Lock()
+			s.pendingWaiters--
+		}
+	}
+}
+
+func (s *durabilityManager) waitForJobDurability(ctx context.Context, jobID int) error {
+	s.mu.Lock()
+
+	if jobID <= 0 {
+		s.mu.Unlock()
+		return ErrJobUnknown
+	}
+
+	if s.closeErr != nil {
+		err := s.closeErr
+		s.mu.Unlock()
+		return err
+	}
+
+	if err, ok := s.completedJobs[jobID]; ok {
+		s.mu.Unlock()
+		return err
+	}
+
+	if s.isExpiredLocked(jobID) {
+		s.mu.Unlock()
+		return ErrJobExpired
+	}
+
+	js, inFlight := s.inFlightJobs[jobID]
+	if !inFlight {
+		s.mu.Unlock()
+		return ErrJobUnknown
+	}
+
+	s.pendingWaiters++
+	ch := js.done
+	s.mu.Unlock()
+
+	select {
+	case <-ctx.Done():
+		s.mu.Lock()
+		defer s.mu.Unlock()
+		s.pendingWaiters--
+		if s.closeErr != nil {
+			return s.closeErr
+		}
+		if err, ok := s.completedJobs[jobID]; ok {
+			return err
+		}
+		return ctx.Err()
+	case <-ch:
+		s.mu.Lock()
+		defer s.mu.Unlock()
+		s.pendingWaiters--
+		if s.closeErr != nil {
+			return s.closeErr
+		}
+		if err, ok := s.completedJobs[jobID]; ok {
+			return err
+		}
+		return js.err
+	}
+}
+
+func (s *durabilityManager) durableState() (base.SeqNum, error) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return s.highestDurableSeqNum, s.firstErr
+}
+
+func (s *durabilityManager) notify(seqNum base.SeqNum) <-chan error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	ch := make(chan error, 1)
+
+	if s.closeErr != nil {
+		ch <- s.closeErr
+		return ch
+	}
+
+	if s.firstErr != nil {
+		ch <- s.firstErr
+		return ch
+	}
+
+	if s.isDurableLocked(seqNum) {
+		ch <- nil
+		return ch
+	}
+
+	if len(s.subscriptions) >= s.maxSubscriptions {
+		ch <- ErrTooManyDurabilitySubscriptions
+		return ch
+	}
+
+	s.subscriptions[ch] = seqNum
+	return ch
+}
+
+func (s *durabilityManager) stats() DurabilityStats {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	return DurabilityStats{
+		HighestDurableSeqNum:   s.highestDurableSeqNum,
+		FirstErr:               s.firstErr,
+		PendingWaiters:         s.pendingWaiters,
+		TotalDurableCommits:    s.totalDurableCommits,
+		TotalFailedCommits:     s.totalFailedCommits,
+		CumulativeSyncDuration: s.cumulativeSyncDuration,
+		MaxSyncDuration:        s.maxSyncDuration,
+	}
+}
+
+func (s *durabilityManager) getMetrics() (uint64, time.Duration) {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if !s.batchDurableConfigured {
+		return 0, 0
+	}
+	return s.durableCommitCount, s.durableCommitDuration
+}
+
+func (d *DB) getDurabilityManager() *durabilityManager {
+	if d.durability == nil {
+		d.durability = newDurabilityManager(false)
+	}
+	return d.durability
+}
+
+// WaitForDurability blocks until a sequence number is durable; zero succeeds
+// after any commit.
+func (d *DB) WaitForDurability(seqNum base.SeqNum) error {
+	return d.WaitForDurabilityContext(context.Background(), seqNum)
+}
+
+// WaitForDurabilityContext blocks until a sequence number is durable; zero succeeds
+// after any commit. Durability and close errors take precedence over context cancellation.
+func (d *DB) WaitForDurabilityContext(ctx context.Context, seqNum base.SeqNum) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+	return d.getDurabilityManager().waitForDurability(ctx, seqNum)
+}
+
+// WaitForDurabilityBatch blocks until every sequence number in a slice is durable;
+// nil/empty returns nil.
+func (d *DB) WaitForDurabilityBatch(seqNums []base.SeqNum) error {
+	return d.WaitForDurabilityBatchContext(context.Background(), seqNums)
+}
+
+// WaitForDurabilityBatchContext blocks until every sequence number in a slice is durable;
+// nil/empty returns nil. Durability and close errors take precedence over context cancellation.
+func (d *DB) WaitForDurabilityBatchContext(ctx context.Context, seqNums []base.SeqNum) error {
+	if len(seqNums) == 0 || d.opts.DisableWAL {
+		return nil
+	}
+	maxSeq := seqNums[0]
+	for _, s := range seqNums[1:] {
+		if s > maxSeq {
+			maxSeq = s
+		}
+	}
+	return d.WaitForDurabilityContext(ctx, maxSeq)
+}
+
+// WaitForJobDurability waits by callback job ID. Jobs outside a bounded retention
+// window get an error containing "expired"; never-seen and zero IDs get an error
+// containing "unknown".
+func (d *DB) WaitForJobDurability(jobID int) error {
+	return d.WaitForJobDurabilityContext(context.Background(), jobID)
+}
+
+// WaitForJobDurabilityContext waits by callback job ID. Jobs outside a bounded retention
+// window get an error containing "expired"; never-seen and zero IDs get an error
+// containing "unknown". Durability and close errors take precedence over context cancellation.
+func (d *DB) WaitForJobDurabilityContext(ctx context.Context, jobID int) error {
+	if d.opts.DisableWAL {
+		return nil
+	}
+	return d.getDurabilityManager().waitForJobDurability(ctx, jobID)
+}
+
+// DurableState returns the highest durable sequence number and first latched error.
+func (d *DB) DurableState() (base.SeqNum, error) {
+	return d.getDurabilityManager().durableState()
+}
+
+// DurabilityNotify returns a pre-filled receive-only channel that delivers nil
+// on success or a non-nil error on WAL sync failure or DB close. Outstanding
+// subscriptions are bounded; excess callers get a pre-filled channel with an
+// immediate non-nil error.
+func (d *DB) DurabilityNotify(seqNum base.SeqNum) <-chan error {
+	if d.opts.DisableWAL {
+		ch := make(chan error, 1)
+		ch <- nil
+		return ch
+	}
+	return d.getDurabilityManager().notify(seqNum)
+}
+
+// DurabilityStats returns a snapshot of durability statistics.
+func (d *DB) DurabilityStats() DurabilityStats {
+	return d.getDurabilityManager().stats()
+}
