@@ -0,0 +1,552 @@
+// Copyright 2026 The LevelDB-Go and Pebble Authors. All rights reserved. Use
+// of this source code is governed by a BSD-style license that can be found in
+// the LICENSE file.
+
+package pebble
+
+import (
+	"context"
+	"sync"
+	"sync/atomic"
+	"testing"
+	"time"
+
+	"github.com/cockroachdb/errors"
+	"github.com/cockroachdb/pebble/internal/base"
+	"github.com/cockroachdb/pebble/vfs"
+	"github.com/cockroachdb/pebble/vfs/errorfs"
+	"github.com/stretchr/testify/require"
+)
+
+func TestBatchDurableCallback(t *testing.T) {
+	var mu sync.Mutex
+	var events []BatchDurableInfo
+
+	opts := &Options{
+		FS: vfs.NewMem(),
+		EventListener: &EventListener{
+			BatchDurable: func(info BatchDurableInfo) {
+				mu.Lock()
+				defer mu.Unlock()
+				events = append(events, info)
+			},
+		},
+	}
+
+	db, err := Open("", opts)
+	require.NoError(t, err)
+	defer db.Close()
+
+	// Initial stats before any commits.
+	stats := db.DurabilityStats()
+	require.Equal(t, base.SeqNum(0), stats.HighestDurableSeqNum)
+	require.Nil(t, stats.FirstErr)
+	require.Equal(t, int64(0), stats.PendingWaiters)
+	require.Equal(t, uint64(0), stats.TotalDurableCommits)
+	require.Equal(t, uint64(0), stats.TotalFailedCommits)
+	require.Equal(t, time.Duration(0), stats.CumulativeSyncDuration)
+	require.Equal(t, time.Duration(0), stats.MaxSyncDuration)
+
+	m := db.Metrics()
+	require.Equal(t, uint64(0), m.DurableCommitCount)
+	require.Equal(t, time.Duration(0), m.DurableCommitDuration)
+
+	// Non-sync commit must never trigger BatchDurable.
+	err = db.Set([]byte("k1"), []byte("v1"), NoSync)
+	require.NoError(t, err)
+
+	mu.Lock()
+	require.Len(t, events, 0)
+	mu.Unlock()
+
+	// Sync commit with CorrelationID.
+	wo := &WriteOptions{
+		Sync:                true,
+		CommitCorrelationID: 12345,
